def absoluteGaloisGroupRestrictEquiv :
    Field.absoluteGaloisGroup K ≃ₜ* AbsoluteGaloisGroup K :=
  separableClosureRestrictEquiv K (AlgebraicClosure K)

def KaehlerDifferential : Type v :=
  (KaehlerDifferential.ideal R S).Cotangent
deriving Inhabited

def KaehlerDifferential.linearMapEquivDerivation : (Ω[S⁄R] →ₗ[S] M) ≃ₗ[S] Derivation R S M :=
  { Derivation.llcomp.flip <| KaehlerDifferential.D R S with
    invFun := Derivation.liftKaehlerDifferential
    left_inv := fun _ =>
      Derivation.liftKaehlerDifferential_unique _ _ (Derivation.liftKaehlerDifferential_comp _)
    right_inv := Derivation.liftKaehlerDifferential_comp }

def BDeRhamPlus : Type u :=
  AdicCompletion (RingHom.ker (fontaineThetaInvertP R p)) (Localization.Away (p : 𝕎 R♭))
deriving CommRing

def BDeRham : Type u :=
  Localization (M := BDeRhamPlus R p) <| Submonoid.closure <|
    AdicCompletion.of ((RingHom.ker (fontaineThetaInvertP R p))) _ ''
      {a | (RingHom.ker (fontaineThetaInvertP R p)) = Ideal.span {a}}
